def add_entry(entry: dict):
    catalogue.append(entry)

def get_entry(uid: str):
    return next((e for e in catalogue if e.get("UniqueID") == uid), None)

def list_entries():
    return catalogue

def export_catalogue_to_excel(catalogue, filename="catalogue.xlsx"):
    df = pd.DataFrame(catalogue)
    df.to_excel(filename, index=False)
    print(f"Catalogue exported to {filename}")

if __name__ == "__main__":
    print("Catalogue contains", len(catalogue), "entries")
    export_catalogue_to_excel(catalogue, "Opensees_Model_Catalogue.xlsx")
